import { useEffect, useState } from "react";

type ScriptItem = {
  id: string;
  scene: string;
  product_id?: string;
  intent: string;
  title?: string;
  text: string;
  enabled?: boolean;
  priority?: number;
  tags?: string[];
};

type Stats = {
  script_count?: number;
  enabled_count?: number;
  event_count?: number;
  totals?: Record<string, number>;
};

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    headers: { "Content-Type": "application/json", ...(init?.headers || {}) },
    ...init,
  });
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

export default function ScriptsPage() {
  const [items, setItems] = useState<ScriptItem[]>([]);
  const [stats, setStats] = useState<Stats>({});
  const [editing, setEditing] = useState<ScriptItem | null>(null);
  const [form, setForm] = useState({
    scene: "default",
    product_id: "",
    intent: "generic",
    title: "",
    text: "",
    priority: 0,
    enabled: true,
    tags: "",
  });
  const [q, setQ] = useState("");
  const [error, setError] = useState("");

  async function load() {
    try {
      const suffix = q ? `?q=${encodeURIComponent(q)}` : "";
      const data = await api<{ items: ScriptItem[] }>(`/api/scripts${suffix}`);
      setItems(data.items || []);
      setStats(await api<Stats>("/api/scripts/stats"));
      setError("");
    } catch (e) {
      setError(String(e));
    }
  }

  useEffect(() => {
    load();
  }, []);

  function edit(item: ScriptItem) {
    setEditing(item);
    setForm({
      scene: item.scene || "default",
      product_id: item.product_id || "",
      intent: item.intent || "generic",
      title: item.title || "",
      text: item.text || "",
      priority: item.priority || 0,
      enabled: item.enabled !== false,
      tags: (item.tags || []).join(","),
    });
  }

  function reset() {
    setEditing(null);
    setForm({ scene: "default", product_id: "", intent: "generic", title: "", text: "", priority: 0, enabled: true, tags: "" });
  }

  async function save() {
    const body = {
      ...form,
      product_id: form.product_id || undefined,
      tags: form.tags.split(",").map((x) => x.trim()).filter(Boolean),
    };
    if (editing) {
      await api(`/api/scripts/${editing.id}`, { method: "PUT", body: JSON.stringify(body) });
    } else {
      await api("/api/scripts", { method: "POST", body: JSON.stringify(body) });
    }
    reset();
    await load();
  }

  async function remove(id: string) {
    if (!confirm("确认删除这条话术？")) return;
    await api(`/api/scripts/${id}`, { method: "DELETE" });
    await load();
  }

  return (
    <div className="space-y-6">
      <header>
        <h1 className="text-2xl font-bold text-white">话术工作台</h1>
        <p className="text-sm text-slate-400">管理场景、商品、意图对应的话术模板。</p>
      </header>

      {error && <div className="rounded-lg border border-red-500/40 bg-red-950/40 p-3 text-sm text-red-200">{error}</div>}

      <section className="grid grid-cols-2 gap-4 md:grid-cols-4">
        {[
          ["话术数", stats.script_count ?? items.length],
          ["启用数", stats.enabled_count ?? items.filter((x) => x.enabled !== false).length],
          ["事件数", stats.event_count ?? 0],
          ["播放数", stats.totals?.play ?? 0],
        ].map(([k, v]) => (
          <div key={String(k)} className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
            <div className="text-sm text-slate-400">{k}</div>
            <div className="mt-2 text-2xl font-semibold text-cyan-300">{v}</div>
          </div>
        ))}
      </section>

      <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
        <h2 className="mb-3 font-semibold text-white">{editing ? "编辑话术" : "创建话术"}</h2>
        <div className="grid gap-3 md:grid-cols-3">
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="场景" value={form.scene} onChange={(e) => setForm({ ...form, scene: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="商品ID，可空" value={form.product_id} onChange={(e) => setForm({ ...form, product_id: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="意图" value={form.intent} onChange={(e) => setForm({ ...form, intent: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="标题" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="标签，逗号分隔" value={form.tags} onChange={(e) => setForm({ ...form, tags: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" type="number" placeholder="优先级" value={form.priority} onChange={(e) => setForm({ ...form, priority: Number(e.target.value) })} />
          <textarea className="min-h-24 rounded bg-slate-950 p-2 text-white md:col-span-3" placeholder="话术内容，支持 {商品名}{价格}{卖点}" value={form.text} onChange={(e) => setForm({ ...form, text: e.target.value })} />
        </div>
        <div className="mt-3 flex gap-2">
          <button onClick={save} className="rounded bg-cyan-500 px-4 py-2 font-medium text-slate-950">保存</button>
          <button onClick={reset} className="rounded bg-slate-800 px-4 py-2 text-slate-200">清空</button>
        </div>
      </section>

      <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
        <div className="mb-3 flex gap-2">
          <input className="flex-1 rounded bg-slate-950 p-2 text-white" placeholder="搜索话术" value={q} onChange={(e) => setQ(e.target.value)} />
          <button onClick={load} className="rounded bg-slate-800 px-4 py-2 text-white">搜索</button>
        </div>
        <div className="divide-y divide-slate-800">
          {items.map((item) => (
            <div key={item.id} className="py-3">
              <div className="flex justify-between gap-4">
                <div>
                  <div className="font-medium text-white">{item.title || item.intent}</div>
                  <div className="text-xs text-slate-400">{item.scene} / {item.product_id || "通用"} / {item.intent}</div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => edit(item)} className="text-cyan-300">编辑</button>
                  <button onClick={() => remove(item.id)} className="text-red-300">删除</button>
                </div>
              </div>
              <p className="mt-2 text-sm text-slate-300">{item.text}</p>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
