import { useEffect, useState } from "react";

type Session = {
  id: string;
  title: string;
  status?: string;
  start_at?: string;
  end_at?: string;
  comment_count?: number;
  order_count?: number;
};

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    headers: { "Content-Type": "application/json", ...(init?.headers || {}) },
    ...init,
  });
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

export default function ReportsPage() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selected, setSelected] = useState<Session | null>(null);
  const [report, setReport] = useState("");
  const [form, setForm] = useState({ title: "直播会话", products: "" });
  const [error, setError] = useState("");

  async function load() {
    try {
      const data = await api<{ items: Session[] }>("/api/sessions");
      setSessions(data.items || []);
      setError("");
    } catch (e) {
      setError(String(e));
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function create() {
    const products = form.products
      .split("\n")
      .map((name, i) => ({ product_id: `p${i + 1}`, name: name.trim() }))
      .filter((x) => x.name);
    await api("/api/sessions", { method: "POST", body: JSON.stringify({ title: form.title, products }) });
    setForm({ title: "直播会话", products: "" });
    await load();
  }

  async function openReport(s: Session) {
    setSelected(s);
    const res = await fetch(`/api/sessions/${s.id}/report`);
    setReport(await res.text());
  }

  async function endSession(id: string) {
    await api(`/api/sessions/${id}/end`, { method: "POST" });
    await load();
  }

  return (
    <div className="space-y-6">
      <header>
        <h1 className="text-2xl font-bold text-white">播后复盘</h1>
        <p className="text-sm text-slate-400">直播会话记录、指标汇总和 Markdown 复盘报告。</p>
      </header>

      {error && <div className="rounded border border-red-500/40 bg-red-950/40 p-3 text-red-200">{error}</div>}

      <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
        <h2 className="mb-3 font-semibold text-white">新建会话</h2>
        <div className="grid gap-3 md:grid-cols-2">
          <input className="rounded bg-slate-950 p-2 text-white" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} />
          <textarea className="rounded bg-slate-950 p-2 text-white" placeholder="商品名，每行一个" value={form.products} onChange={(e) => setForm({ ...form, products: e.target.value })} />
        </div>
        <button onClick={create} className="mt-3 rounded bg-cyan-500 px-4 py-2 font-medium text-slate-950">创建</button>
      </section>

      <div className="grid gap-4 lg:grid-cols-2">
        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">会话列表</h2>
          <div className="space-y-3">
            {sessions.map((s) => (
              <div key={s.id} className="rounded-lg border border-slate-800 bg-slate-950/70 p-3">
                <div className="flex justify-between gap-3">
                  <div>
                    <div className="font-medium text-white">{s.title}</div>
                    <div className="text-xs text-slate-400">{s.status}｜评论 {s.comment_count || 0}｜订单 {s.order_count || 0}</div>
                  </div>
                  <div className="flex gap-2 text-sm">
                    <button onClick={() => openReport(s)} className="text-cyan-300">报告</button>
                    {s.status !== "ended" && <button onClick={() => endSession(s.id)} className="text-amber-300">结束</button>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">报告预览 {selected ? `- ${selected.title}` : ""}</h2>
          <pre className="max-h-[620px] overflow-auto whitespace-pre-wrap rounded bg-slate-950 p-4 text-sm text-slate-200">
            {report || "选择一个会话查看复盘报告。"}
          </pre>
        </section>
      </div>
    </div>
  );
}
