import { useEffect, useState } from "react";

type Snapshot = {
  online_count?: number;
  network_latency_ms?: number;
  cpu_percent?: number;
  gpu_percent?: number;
  obs_fps?: number;
  tts_queue_depth?: number;
  status?: string;
  alerts?: Array<{ id: string; severity: string; message: string; created_at: string }>;
};

type EventStats = {
  total?: number;
  by_type?: Record<string, number>;
  by_severity?: Record<string, number>;
  subscribers?: number;
};

async function api<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

export default function DashboardPage() {
  const [snapshot, setSnapshot] = useState<Snapshot>({});
  const [stats, setStats] = useState<EventStats>({});
  const [error, setError] = useState("");

  async function load() {
    try {
      setSnapshot(await api<Snapshot>("/api/dashboard/snapshot"));
      setStats(await api<EventStats>("/api/events/stats"));
      setError("");
    } catch (e) {
      setError(String(e));
    }
  }

  useEffect(() => {
    load();
    const t = setInterval(load, 5000);
    return () => clearInterval(t);
  }, []);

  const cards = [
    ["在线人数", snapshot.online_count ?? 0, "人"],
    ["网络延迟", snapshot.network_latency_ms ?? 0, "ms"],
    ["CPU", snapshot.cpu_percent ?? 0, "%"],
    ["GPU", snapshot.gpu_percent ?? 0, "%"],
    ["OBS帧率", snapshot.obs_fps ?? 0, "fps"],
    ["TTS队列", snapshot.tts_queue_depth ?? 0, "条"],
