  return (
    <div className="space-y-6">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">直播健康度看板</h1>
          <p className="text-sm text-slate-400">实时快照、告警和事件统计。</p>
        </div>
        <button onClick={load} className="rounded bg-slate-800 px-4 py-2 text-sm text-white">刷新</button>
      </header>

      {error && <div className="rounded border border-red-500/40 bg-red-950/40 p-3 text-red-200">{error}</div>}

      <section className="grid grid-cols-2 gap-4 lg:grid-cols-6">
        {cards.map(([name, value, unit]) => (
          <div key={String(name)} className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
            <div className="text-sm text-slate-400">{name}</div>
            <div className="mt-2 text-2xl font-semibold text-cyan-300">{value}<span className="ml-1 text-sm text-slate-500">{unit}</span></div>
          </div>
        ))}
      </section>

      <div className="grid gap-4 lg:grid-cols-2">
        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">事件统计</h2>
          <div className="grid grid-cols-2 gap-3">
            <div className="rounded bg-slate-950 p-3">
              <div className="text-sm text-slate-400">事件总数</div>
              <div className="text-xl text-white">{stats.total ?? 0}</div>
            </div>
            <div className="rounded bg-slate-950 p-3">
              <div className="text-sm text-slate-400">SSE订阅</div>
              <div className="text-xl text-white">{stats.subscribers ?? 0}</div>
            </div>
          </div>
          <div className="mt-4 space-y-2">
            {Object.entries(stats.by_type || {}).map(([k, v]) => (
              <div key={k} className="flex justify-between border-b border-slate-800 pb-1 text-sm">
                <span className="text-slate-300">{k}</span>
                <span className="text-cyan-300">{v}</span>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">实时告警</h2>
          <div className="space-y-2">
            {(snapshot.alerts || []).length === 0 && <div className="text-sm text-slate-400">暂无告警。</div>}
            {(snapshot.alerts || []).map((a) => (
              <div key={a.id} className="rounded border border-amber-500/30 bg-amber-950/30 p-3">
                <div className="text-sm font-medium text-amber-200">{a.severity}</div>
                <div className="text-sm text-slate-200">{a.message}</div>
                <div className="text-xs text-slate-500">{a.created_at}</div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}
