import { useEffect, useState } from "react";

type Asset = {
  id: string;
  name: string;
  asset_type: string;
  tags?: string[];
  duration_seconds?: number;
  resolution?: string;
  file_path?: string;
  thumbnail_path?: string;
  usage_count?: number;
  rating?: number;
};

type Playlist = {
  id: string;
  name: string;
  description?: string;
  asset_ids?: string[];
};

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    headers: { "Content-Type": "application/json", ...(init?.headers || {}) },
    ...init,
  });
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

export default function AssetsPage() {
  const [assets, setAssets] = useState<Asset[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [q, setQ] = useState("");
  const [form, setForm] = useState({ name: "", asset_type: "video", file_path: "", thumbnail_path: "", tags: "", duration_seconds: 0, resolution: "" });
  const [playlistName, setPlaylistName] = useState("");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [error, setError] = useState("");

  async function load() {
    try {
      const search = q ? `/api/assets/search?q=${encodeURIComponent(q)}` : "/api/assets/search";
      setAssets((await api<{ items: Asset[] }>(search)).items || []);
      setPlaylists((await api<{ items: Playlist[] }>("/api/playlists")).items || []);
      setError("");
    } catch (e) {
      setError(String(e));
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function createAsset() {
    await api("/api/assets", {
      method: "POST",
      body: JSON.stringify({ ...form, tags: form.tags.split(",").map((x) => x.trim()).filter(Boolean) }),
    });
    setForm({ name: "", asset_type: "video", file_path: "", thumbnail_path: "", tags: "", duration_seconds: 0, resolution: "" });
    await load();
  }

  async function createPlaylist() {
    await api("/api/playlists", {
      method: "POST",
      body: JSON.stringify({ name: playlistName || "新播放列表", asset_ids: selectedIds }),
    });
    setPlaylistName("");
    setSelectedIds([]);
    await load();
