        <h2 className="mb-3 font-semibold text-white">新增素材</h2>
        <div className="grid gap-3 md:grid-cols-3">
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="名称" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
          <select className="rounded bg-slate-950 p-2 text-white" value={form.asset_type} onChange={(e) => setForm({ ...form, asset_type: e.target.value })}>
            <option>video</option><option>image</option><option>audio</option><option>text</option><option>other</option>
          </select>
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="标签，逗号分隔" value={form.tags} onChange={(e) => setForm({ ...form, tags: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="文件路径" value={form.file_path} onChange={(e) => setForm({ ...form, file_path: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="缩略图路径" value={form.thumbnail_path} onChange={(e) => setForm({ ...form, thumbnail_path: e.target.value })} />
          <input className="rounded bg-slate-950 p-2 text-white" placeholder="分辨率" value={form.resolution} onChange={(e) => setForm({ ...form, resolution: e.target.value })} />
        </div>
        <button onClick={createAsset} className="mt-3 rounded bg-cyan-500 px-4 py-2 font-medium text-slate-950">保存素材</button>
      </section>

      <div className="grid gap-4 lg:grid-cols-3">
        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 lg:col-span-2">
          <div className="mb-3 flex gap-2">
            <input className="flex-1 rounded bg-slate-950 p-2 text-white" placeholder="搜索素材" value={q} onChange={(e) => setQ(e.target.value)} />
            <button onClick={load} className="rounded bg-slate-800 px-4 py-2 text-white">搜索</button>
          </div>
          <div className="space-y-2">
            {assets.map((a) => (
              <div key={a.id} className="flex items-center justify-between rounded border border-slate-800 bg-slate-950/70 p-3">
                <div className="flex items-center gap-3">
                  <input type="checkbox" checked={selectedIds.includes(a.id)} onChange={() => toggle(a.id)} />
                  <div>
                    <div className="font-medium text-white">{a.name}</div>
                    <div className="text-xs text-slate-400">{a.asset_type}｜{a.resolution || "-"}｜使用 {a.usage_count || 0}｜评分 {a.rating || 0}</div>
                    <div className="text-xs text-slate-500">{(a.tags || []).join(", ")}</div>
                  </div>
                </div>
                <button onClick={() => removeAsset(a.id)} className="text-sm text-red-300">删除</button>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">播放列表</h2>
          <input className="mb-2 w-full rounded bg-slate-950 p-2 text-white" placeholder="播放列表名" value={playlistName} onChange={(e) => setPlaylistName(e.target.value)} />
          <button onClick={createPlaylist} className="mb-4 rounded bg-cyan-500 px-4 py-2 text-sm font-medium text-slate-950">用所选素材创建</button>
          <div className="space-y-2">
            {playlists.map((p) => (
              <div key={p.id} className="rounded border border-slate-800 bg-slate-950 p-3">
                <div className="text-white">{p.name}</div>
                <div className="text-xs text-slate-400">{p.asset_ids?.length || 0} 个素材</div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}
