import { useEffect, useState } from "react";

type EventItem = {
  id: string;
  type: string;
  severity: string;
  title?: string;
  message?: string;
  source?: string;
  created_at: string;
  payload?: Record<string, unknown>;
};

type Stats = {
  total?: number;
  by_type?: Record<string, number>;
  by_severity?: Record<string, number>;
  subscribers?: number;
};

async function api<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(await res.text());
  return res.json();
}

export default function EventsPage() {
  const [live, setLive] = useState<EventItem[]>([]);
  const [history, setHistory] = useState<EventItem[]>([]);
  const [stats, setStats] = useState<Stats>({});
  const [filter, setFilter] = useState({ type: "", severity: "" });
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState("");

  async function load() {
    const params = new URLSearchParams();
    if (filter.type) params.set("type", filter.type);
    if (filter.severity) params.set("severity", filter.severity);
    params.set("limit", "200");
    setHistory((await api<{ items: EventItem[] }>(`/api/events/query?${params}`)).items || []);
    setStats(await api<Stats>("/api/events/stats"));
  }

  useEffect(() => {
    load().catch((e) => setError(String(e)));
  }, []);

  useEffect(() => {
    const es = new EventSource("/api/events/stream");
    es.onopen = () => setConnected(true);
    es.onerror = () => setConnected(false);
    const handler = (ev: MessageEvent) => {
      try {
        const item = JSON.parse(ev.data) as EventItem;
        setLive((prev) => [item, ...prev].slice(0, 100));
      } catch {
        return;
      }
    };
    ["pipeline_step", "tts_play", "comment_match", "popup_show", "alert_fire", "message"].forEach((t) => es.addEventListener(t, handler));
    return () => es.close();
  }, []);

  const eventRow = (e: EventItem) => (
    <div key={e.id} className="rounded border border-slate-800 bg-slate-950/70 p-3">
      <div className="flex justify-between gap-3">
        <div>
          <div className="font-medium text-white">{e.title || e.type}</div>
          <div className="text-sm text-slate-300">{e.message || "-"}</div>
        </div>
        <div className="text-right text-xs">
          <div className="text-cyan-300">{e.type}</div>
          <div className="text-slate-400">{e.severity}</div>
        </div>
      </div>
      <div className="mt-2 text-xs text-slate-500">{e.source || "phs"}｜{e.created_at}</div>
    </div>
  );

  return (
    <div className="space-y-6">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">事件日志</h1>
          <p className="text-sm text-slate-400">SSE实时流、历史查询和统计。</p>
        </div>
        <span className={`rounded px-3 py-1 text-sm ${connected ? "bg-emerald-500/20 text-emerald-300" : "bg-red-500/20 text-red-300"}`}>
          {connected ? "SSE已连接" : "SSE断开"}
        </span>
      </header>

      {error && <div className="rounded border border-red-500/40 bg-red-950/40 p-3 text-red-200">{error}</div>}

      <section className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <div className="text-sm text-slate-400">事件总数</div>
          <div className="mt-2 text-2xl text-cyan-300">{stats.total ?? 0}</div>
        </div>
        <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <div className="text-sm text-slate-400">订阅数</div>
          <div className="mt-2 text-2xl text-cyan-300">{stats.subscribers ?? 0}</div>
        </div>
        <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 md:col-span-2">
          <div className="text-sm text-slate-400">严重级别</div>
          <div className="mt-2 flex flex-wrap gap-2 text-xs">
            {Object.entries(stats.by_severity || {}).map(([k, v]) => <span key={k} className="rounded bg-slate-800 px-2 py-1 text-slate-200">{k}: {v}</span>)}
          </div>
        </div>
      </section>

      <div className="grid gap-4 lg:grid-cols-2">
        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <h2 className="mb-3 font-semibold text-white">实时事件</h2>
          <div className="max-h-[650px] space-y-2 overflow-auto">
            {live.length === 0 && <div className="text-sm text-slate-400">等待事件推送。</div>}
            {live.map(eventRow)}
          </div>
        </section>

        <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4">
          <div className="mb-3 flex gap-2">
